import java.util.concurrent.Executors;
import java.util.concurrent.ExecutorService;
import java.time.Duration;

public class ScalableTaskProcessor {
    // Utilizing Virtual Threads (Project Loom) for high scalability and throughput
    public static void main(String[] args) throws InterruptedException {
        try (ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < 10_000; i++) {
                final int taskId = i;
                executor.submit(() -> {
                    long start = System.nanoTime();
                    // Simulate blocking I/O or downstream call
                    Thread.sleep(Duration.ofMillis(50));
                    long duration = (System.nanoTime() - start) / 1_000_000;
                    System.out.println("Task " + taskId + " completed in " + duration + "ms");
                    return null;
                });
            }
        } // Executor scope automatically closes, awaiting termination
    }
}
